const {
  readdirSync,
  readFileSync,
  writeFileSync,
  existsSync,
  unlinkSync,
} = require("fs-extra"); 
const axios = require('axios');

global.json = require('jsonfile'); 

module.exports.onLoad = function () {
  const pathData = __dirname + "/cache/anti.json"; 

  if (!global.anti) {
    global.anti = pathData;
  }

  if (!existsSync(pathData)) {
    const defaultData = {
      boxname: [],
      boximage: [],
      antiNickname: [],
      antiout: {},
      antiBotNickname: {}, 
      antiEmoji: {},       
      antiTheme: {},       
      antiWar: {}          
    };
    writeFileSync(pathData, json.stringify(defaultData, null, 4));
    console.log("đã tạo file anti mới.");
  } else {
    try {
      let data = json.parse(readFileSync(pathData, "utf8"));
      if (!data.boxname) data.boxname = [];
      if (!data.boximage) data.boximage = [];
      if (!data.antiNickname) data.antiNickname = [];
      if (!data.antiout) data.antiout = {};
      if (!data.antiBotNickname) data.antiBotNickname = {}; 
      if (!data.antiEmoji) data.antiEmoji = {};             
      if (!data.antiTheme) data.antiTheme = {};             
      if (!data.antiWar) data.antiWar = {};                 
      writeFileSync(pathData, json.stringify(data, null, 4)); 
      console.log("kiểm tra file anti");
    } catch (e) {
      const defaultData = { 
        boxname: [], boximage: [], antiNickname: [], antiout: {},
        antiBotNickname: {}, antiEmoji: {}, antiTheme: {}, antiWar: {}
      };
      writeFileSync(pathData, json.stringify(defaultData, null, 4));
    }
  }
};

module.exports.handleEvent = async function ({ api, event, users }) {
  const { threadid, logmessagetype, logmessagedata, author, messageid } = event;
  const pathData = global.anti;
  const dataAnti = json.parse(readFileSync(pathData, "utf8"));

  const botid = api.getCurrentUserID();

  if (dataAnti.antiBotNickname[threadid] && logmessagetype === "change_thread_nickname") {
      const { participantid, newnickname } = logmessagedata;
      if (participantid === botid) { 
          const originalnickname = dataAnti.antiBotNickname[threadid];
          if (newnickname !== originalnickname) {
              api.changeNickname(originalnickname, threadid, botid);
              return api.sendMessage(`anti namebot đã phát hiện đổi biệt danh của bot. đang đặt lại biệt danh cũ: "${originalnickname}"`, threadid);
          }
      }
  }

  if (dataAnti.antiEmoji[threadid] && logmessagetype === "change_thread_emoji") {
      const { newemoji } = logmessagedata;
      const originalemoji = dataAnti.antiEmoji[threadid];
      if (newemoji !== originalemoji) {
          api.changeThreadEmoji(originalemoji, threadid);
          return api.sendMessage(`anti emoji đã phát hiện đổi emoji nhóm. đang đặt lại emoji cũ: ${originalemoji}`, threadid);
      }
  }

  if (dataAnti.antiTheme[threadid] && logmessagetype === "change_thread_color") {
      const { newthemeid } = logmessagedata; 
      const originalthemeid = dataAnti.antiTheme[threadid];
      if (newthemeid !== originalthemeid) {
          api.changeThreadColor(originalthemeid, threadid);
          return api.sendMessage(`anti theme đã phát hiện đổi theme nhóm. đang đặt lại theme cũ.`, threadid);
      }
  }

  if (dataAnti.antiout[threadid] && logmessagetype === "log:unsubscribe") {
      const leftmemberid = logmessagedata.participant_id;
      if (leftmemberid !== botid) { 
          const name = await users.getName(leftmemberid);
          api.addUserToGroup(leftmemberid, threadid, (err) => {
              if (err) return api.sendMessage(`anti out không thể thêm lại ${name} vào nhóm. có thể do cài đặt riêng tư của người dùng hoặc bot không có quyền quản trị viên.`, threadid);
              api.sendMessage(`anti out ${name} vừa rời nhóm nhưng đã được thêm lại thành công!`, threadid);
          });
      }
  }

  if (dataAnti.antiWar[threadid]) {
      const spamthreshold = 5; 
      const spamtimewindow = 10000; 

      if (!global.spamData) global.spamData = {};
      if (!global.spamData[threadid]) global.spamData[threadid] = {};
      if (!global.spamData[threadid][author]) global.spamData[threadid][author] = { count: 0, timer: null };

      const userData = global.spamData[threadid][author];
      userData.count++;

      if (userData.timer) clearTimeout(userData.timer); 

      userData.timer = setTimeout(() => {
          userData.count = 0; 
          userData.timer = null;
      }, spamtimewindow);

      if (userData.count >= spamthreshold) {
          api.sendMessage(`anti war phát hiện spam từ ${await users.getName(author)}. đã tạm thời bỏ qua tin nhắn.`, threadid, messageid);

          userData.count = 0; 
      }
  }
};


module.exports.handleReply = async function ({ api, event, args, handlereply }) {
