      writeFileSync(pathData, json.stringify(dataAnti, null, 4));
      break;
    }
    case "4": { 
      if (!checkpermssion("anti out")) return;
      if (dataAnti.antiout[threadid] == true) {
        dataAnti.antiout[threadid] = false;
        api.sendMessage("✅ tắt thành công chế độ anti out!", threadid, messageid);
      } else {
        dataAnti.antiout[threadid] = true;
        api.sendMessage("✅ bật thành công chế độ anti out!", threadid, messageid);
      }
      writeFileSync(pathData, json.stringify(dataAnti, null, 4));
      break;
    }
    case "5": { 
      if (!checkpermssion("anti biệt danh bot")) return;
      const botid = api.getCurrentUserID();
      const currentbotnickname = (await api.getThreadInfo(threadid)).nicknames[botid];
      if (dataAnti.antiBotNickname[threadid]) {
          delete dataAnti.antiBotNickname[threadid];
          api.sendMessage("✅ tắt thành công chế độ anti đổi biệt danh bot.", threadid, messageid);
      } else {
          dataAnti.antiBotNickname[threadid] = currentbotnickname;
          api.sendMessage("✅ bật thành công chế độ anti đổi biệt danh bot. biệt danh gốc: \"" + currentbotnickname + "\"", threadid, messageid);
      }
      writeFileSync(pathData, json.stringify(dataAnti, null, 4));
      break;
    }
    case "6": { 
      if (!checkpermssion("anti emoji nhóm")) return;
      const currentemoji = (await api.getThreadInfo(threadid)).emoji;
      if (dataAnti.antiEmoji[threadid]) {
          delete dataAnti.antiEmoji[threadid];
          api.sendMessage("✅ tắt thành công chế độ anti đổi emoji nhóm.", threadid, messageid);
      } else {
          dataAnti.antiEmoji[threadid] = currentemoji;
          api.sendMessage("✅ bật thành công chế độ anti đổi emoji nhóm. emoji gốc: " + currentemoji, threadid, messageid);
      }
      writeFileSync(pathData, json.stringify(dataAnti, null, 4));
      break;
    }
    case "7": { 
      if (!checkpermssion("anti theme nhóm")) return;
      const currenttheme = (await api.getThreadInfo(threadid)).color; 
      if (dataAnti.antiTheme[threadid]) {
          delete dataAnti.antiTheme[threadid];
          api.sendMessage("✅ tắt thành công chế độ anti đổi theme nhóm.", threadid, messageid);
      } else {
          dataAnti.antiTheme[threadid] = currenttheme;
          api.sendMessage("✅ bật thành công chế độ anti đổi theme nhóm. đã lưu theme hiện tại.", threadid, messageid);
      }
      writeFileSync(pathData, json.stringify(dataAnti, null, 4));
      break;
    }
    case "8": { 
      if (!checkpermssion("anti war (chống spam)")) return;
      if (dataAnti.antiWar[threadid] == true) {
        dataAnti.antiWar[threadid] = false;
        api.sendMessage("✅ tắt thành công chế độ anti war (chống spam).", threadid, messageid);
      } else {
        dataAnti.antiWar[threadid] = true;
        api.sendMessage("✅ bật thành công chế độ anti war (chống spam).", threadid, messageid);
      }
      writeFileSync(pathData, json.stringify(dataAnti, null, 4));
      break;
    }
    case "9": { 
      const antiimage = dataAnti.boximage.find((item) => item.threadid === threadid);
      const antiboxname = dataAnti.boxname.find((item) => item.threadid === threadid);
      const antinickname = dataAnti.antiNickname.find((item) => item.threadid === threadid);
      const antibotnickname = dataAnti.antiBotNickname[threadid];
      const antiemoji = dataAnti.antiEmoji[threadid];
      const antitheme = dataAnti.antiTheme[threadid];
      const antiwar = dataAnti.antiWar[threadid];

      return api.sendMessage(
        `---- check anti ----\n` +
        `↪ anti avt box: ${antiimage ? "bật" : "tắt"}\n` +
        `↪ anti name box: ${antiboxname ? "bật" : "tắt"}\n` +
        `↪ anti nick name: ${antinickname ? "bật" : "tắt"}\n` +
        `↪ anti out: ${dataAnti.antiout[threadid] ? "bật" : "tắt"}\n` +
        `↪ anti biệt danh bot: ${antibotnickname ? "bật" : "tắt"}\n` +
        `↪ anti emoji box: ${antiemoji ? "bật" : "tắt"}\n` +
        `↪ anti theme box: ${antitheme ? "bật" : "tắt"}\n` +
        `↪ anti war (spam): ${antiwar ? "bật" : "tắt"}`,
        threadid
      );
      break;
    }

    default: {
      return api.sendMessage(
        `số bạn chọn không có trong danh sách anti! vui lòng chọn từ 1 đến 9.`,
        threadid
      );
    }
  }
};

module.exports.run = async ({ api, event, args, permssion, threads }) => {
  const { threadid, messageid, senderid } = event;
  const threadSetting = (await threads.getData(String(threadid))).data || {};
  const prefix = threadSetting.hasOwnProperty("prefix")
    ? threadSetting.prefix
    : global.config.prefix;

  return api.sendMessage(
        `chế độ anti có thể đặt\n────────────────\n` +
        `1. anti boxname: cấm đổi tên nhóm\n` +
        `2. anti avtbox: cấm đổi ảnh nhóm\n` +
        `3. anti name: cấm đổi biệt danh\n` +
        `4. anti out: cấm thoát nhóm\n` +
        `5. anti namebot: cấm đổi biệt danh bot\n` +
        `6. anti emoji: cấm đổi emoji nhóm\n` +
        `7. anti theme: cấm đổi theme nhóm\n` +
        `8. anti war: cấm spam tin nhắn/ảnh\n` +
        `9. check: kiểm tra danh sách đã bật anti của box\n\n` +
        `📌 phản hồi tin nhắn này kèm số thứ tự mà bạn muốn chọn để bật hoặc tắt!`,
        threadid, (error, info) => {
            if (error) {
              return api.sendMessage("đã xảy ra lỗi!", threadid);
            } else {
              global.client.handleReply.push({
                name: this.config.name,
                messageid: info.messageid,
                author: senderid,
                permssion
              });
            }
          });
};
